<style id="business-report-styles">
.bm-workspace.br-reference-workspace{--report-purple:#7c3aed;--report-indigo:#6366f1;max-width:none;padding:15px 0 32px;background:linear-gradient(180deg,#e9e5f6 0,#eeedf5 300px);color:#111827}.br-reference-workspace>.bm-hero,.br-reference-workspace>.bm-navigation{display:none}.br-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin-bottom:32px}.br-kpi{border:1px solid #f5f3ff;background:#fff;border-radius:17px;padding:20px;box-shadow:0 8px 24px #7c3aed0a;transition:transform .25s,box-shadow .25s;min-height:147px}.br-kpi:hover{transform:translateY(-3px);box-shadow:0 12px 28px #7c3aed14}.br-kpi-icon{width:42px;height:42px;border-radius:12px;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#ede9fe,#e0e7ff);color:#7c3aed;font-size:18px;margin-bottom:11px}.br-kpi-value{font-size:28px;font-weight:800;line-height:1.1;letter-spacing:-.3px}.br-kpi-label{margin-top:5px;color:#9ca3af;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.4px}.br-filter-bar{padding:17px;background:#fff;border-radius:17px;border:1px solid #f1eefe;box-shadow:0 8px 24px #7c3aed09;margin-bottom:20px}.br-filter-grid{display:grid;grid-template-columns:repeat(7,minmax(85px,1fr)) auto auto;align-items:end;gap:15px}.br-reference-workspace .br-filter-bar label{display:block;font-size:10px;text-transform:uppercase;font-weight:700;letter-spacing:.5px;color:#9ca3af;margin:0 0 6px}.br-reference-workspace .br-filter-bar .form-control{border:1px solid #e9e5fc;border-radius:10px;background:#fbfaff;color:#4b5563;font-size:12px;min-height:41px;height:41px;padding:8px 12px;box-shadow:none}.br-reference-workspace .form-control:focus{border-color:#9c78f8;box-shadow:0 0 0 3px #7c3aed14}.br-reference-workspace .btn.br-apply{display:flex;align-items:center;justify-content:center;gap:7px;background:linear-gradient(135deg,#7c3aed,#6366f1);border:0;color:#fff;padding:11px 19px;height:40px;font-weight:700;border-radius:10px;font-size:12px}.br-reference-workspace .btn.br-reset{display:flex;align-items:center;justify-content:center;gap:7px;background:#f8f9fb;color:#1f2937;font-size:12px;border:0;padding:8px 10px;height:34px;margin-bottom:3px}.br-custom-range{display:flex;gap:16px;margin-top:16px;max-width:450px}.br-custom-range>div{flex:1}.br-main-card{background:#fff;border-radius:21px;padding:26px;box-shadow:0 10px 28px #7c3aed0b}.br-card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-bottom:32px}.br-total-label{color:#10b981;font-size:11px;text-transform:uppercase;letter-spacing:.6px;font-weight:800;margin-bottom:7px}.br-total-value{font-size:36px;line-height:1.15;font-weight:800;letter-spacing:-.7px;min-height:42px}.br-chart-tabs{display:flex;gap:3px;background:#f5f3ff;border-radius:12px;padding:4px;flex-wrap:wrap}.br-chart-tabs button{border:0;display:flex;align-items:center;justify-content:center;gap:7px;background:transparent;color:#6d28d9;font-size:12px;font-weight:700;padding:10px 14px;border-radius:9px;cursor:pointer;transition:background .2s,box-shadow .2s}.br-chart-tabs button[aria-selected=true]{background:#fff;color:#5b21b6;box-shadow:0 3px 10px #7c3aed20}.br-group-row{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-bottom:21px}.br-group-label{font-size:11px;text-transform:uppercase;color:#6b7280;font-weight:400;margin-bottom:8px}.br-group-chips{display:flex;gap:8px;flex-wrap:wrap}.br-group-chips button{background:#fff;border:1px solid #e9e5fc;border-radius:22px;color:#6d28d9;font-size:11px;font-weight:700;padding:8px 17px;line-height:16px;cursor:pointer;transition:background .2s,box-shadow .2s,color .2s}.br-group-chips button[aria-pressed=true]{background:linear-gradient(135deg,#7c3aed,#6366f1);color:#fff;border-color:transparent;box-shadow:0 4px 10px #7c3aed30}.br-secondary-controls{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.br-view-tabs{display:flex;gap:2px;background:#faf9ff;padding:3px;border:1px solid #efebfd;border-radius:9px}.br-view-tabs button{border:0;background:none;border-radius:6px;padding:7px 11px;font-size:11px;color:#8a7d9f;cursor:pointer}.br-view-tabs button[aria-selected=true]{background:#ede9fe;color:#6d28d9;font-weight:700}.br-reference-workspace .form-control.br-metric-select{min-height:34px;height:34px;max-width:165px;font-size:11px;border-color:#ede9fe;background:#fbfaff;border-radius:9px;padding:5px 9px;color:#6b5c84}.br-replay{border:0;background:#faf9ff;color:#8b78ac;width:32px;height:32px;border-radius:8px;cursor:pointer;font-size:11px}.br-chart-layout{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:20px;align-items:center}.br-plot-wrap{position:relative;min-width:0}.br-chart-stage{height:340px;width:100%;overflow-x:auto;overflow-y:hidden}.br-chart-stage svg{display:block;width:100%;height:100%;overflow:visible}.br-chart-aside{min-width:0;align-self:center}.br-chart-aside #report-chart-legend{height:340px;overflow-y:auto;overscroll-behavior:contain;padding-right:10px;scrollbar-width:thin;scrollbar-color:#999 #f5f5f7}.br-rank-item{padding:13px 0 14px;border-bottom:1px solid #f0eff5;position:relative}.br-rank-item:first-child{padding-top:8px}.br-rank-heading{display:flex;align-items:center;justify-content:space-between;gap:18px;font-size:12px;line-height:1.5}.br-rank-name{display:flex;gap:12px;align-items:center;min-width:0;color:#111827;font-weight:700}.br-rank-name span:last-child{overflow-wrap:anywhere}.br-legend-dot{width:10px;height:10px;border-radius:50%;flex-shrink:0}.br-rank-values{text-align:right;flex-shrink:0;display:flex;flex-direction:column;gap:1px}.br-rank-percent{font-size:13px;color:#111827;font-weight:800;line-height:1.3}.br-rank-quantity{font-size:11px;color:#9ca3af;font-weight:700;white-space:nowrap}.br-rank-track{height:6px;border-radius:8px;background:#f3f4f6;margin-top:8px;width:100%;overflow:hidden}.br-rank-fill{display:block;height:100%;border-radius:8px;transform-origin:left;animation:br-fill-in 1s cubic-bezier(.2,.8,.2,1) both}.br-legend-item{display:flex;align-items:center;gap:10px;padding:13px 0;border-bottom:1px solid #f0eff5;font-size:12px}.br-legend-label{flex:1;min-width:0;overflow-wrap:anywhere}.br-legend-number{font-weight:700}.br-chart-note{font-size:10px;color:#a0a3b0;line-height:1.7;margin:12px 0 0}.br-chart-tooltip{position:absolute;max-width:270px;padding:11px 14px;background:#4c1d95;color:#fff;border-radius:10px;box-shadow:0 8px 22px #5b21b625;z-index:20;pointer-events:none;font-size:12px;line-height:1.7;white-space:pre-line}.br-chart-mark{cursor:pointer;transition:filter .2s}.br-chart-mark:hover,.br-chart-mark:focus{filter:brightness(1.09) drop-shadow(0 3px 5px #7c3aed25);outline:none}.br-chart-empty{height:100%;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:15px;padding:25px;text-align:center;color:#9ca3af;font-size:13px}.br-chart-empty i{font-size:34px;color:#d3c6fa}.br-chart-stage text{font-family:'Source Sans Pro',Arial,sans-serif}.br-content-toolbar{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap;margin:10px 0 18px}.br-content-title{font-size:15px;font-weight:700;color:#4c1d95;margin:24px 0 8px}.br-reference-workspace .dataTables_wrapper .page-item.active .page-link{background:#7c3aed;border-color:#7c3aed}.br-reference-workspace .btn-light{border-color:#ede9fe;color:#6d28d9;background:#faf9ff}.br-reference-workspace button:focus-visible,.br-reference-workspace a:focus-visible{outline:3px solid #c4b5fd;outline-offset:3px}.br-panel-enter{animation:br-panel-in .3s ease-out}.br-wave-flow{stroke-dasharray:3 19;animation:br-flow 9s linear infinite;pointer-events:none}@keyframes br-panel-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}@keyframes br-fill-in{from{transform:scaleX(0)}to{transform:scaleX(1)}}@keyframes br-flow{to{stroke-dashoffset:-220}}
@media(min-width:1600px){.br-filter-bar{padding:20px 17px 24px}.br-kpis{margin-bottom:32px}.br-main-card{padding:26px}.br-chart-stage,.br-chart-aside #report-chart-legend{height:340px}}
@media(max-width:1150px){.br-filter-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.br-filter-grid .br-apply,.br-filter-grid .br-reset{width:100%}.br-group-row{gap:14px}.br-secondary-controls{margin-left:auto}.br-chart-layout{grid-template-columns:5fr 6fr}}
@media(max-width:760px){.br-kpis{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:20px}.br-kpi{padding:17px;min-height:135px}.br-kpi-value{font-size:25px}.br-filter-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.br-main-card{padding:20px}.br-card-top{gap:18px}.br-chart-tabs{gap:1px}.br-chart-tabs button{padding:9px 11px;font-size:11px}.br-total-value{font-size:31px}.br-chart-layout{grid-template-columns:1fr;gap:12px}.br-chart-stage{height:320px}.br-chart-aside #report-chart-legend{height:300px}.br-group-row{margin-bottom:18px}.br-secondary-controls{margin-left:0}.br-group-chips{gap:6px}.br-group-chips button{padding:7px 13px}.br-kpi-label{font-size:10px}}
.br-chart-totals{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;flex:1;min-width:0}.br-chart-total-card{padding:14px 16px;border:1px solid #ede9fe;border-radius:12px;background:#faf9ff}.br-chart-total-activated{background:#f0fdf4;border-color:#dcfce7}.br-chart-total-activated .br-total-label{color:#15803d}.br-chart-total-pending{background:#fffbeb;border-color:#fef3c7}.br-chart-total-pending .br-total-label{color:#b45309}.br-card-top>.br-chart-tabs{margin-left:auto}
@media(max-width:1150px){.br-chart-totals{flex-basis:100%}}
@media(max-width:480px){.br-chart-totals{gap:6px}.br-chart-total-card{padding:10px 8px}.br-chart-total-card .br-total-label{font-size:9px;letter-spacing:0}.br-chart-total-card .br-total-value{font-size:24px;overflow-wrap:anywhere}}
@media(prefers-reduced-motion:reduce){.br-panel-enter,.br-wave-flow,.br-rank-fill{animation:none}.br-kpi,.br-chart-tabs button,.br-group-chips button{transition:none}}
